WITH latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY promo_code, channel ORDER BY ends_on DESC, id) AS latest_rank FROM promotions) ranked WHERE latest_rank = 1) SELECT promo_code, DATE_TRUNC('MONTH', starts_on) AS activity_month, PERCENTILE_APPROX(discount_pct, 0.5) AS discount_pct_p50, STDDEV_SAMP(discount_pct) AS discount_pct_stddev, ROUND(AVG(discount_pct), 2) AS avg_discount_pct, MAX(discount_pct) AS max_discount_pct FROM latest GROUP BY promo_code, activity_month HAVING PERCENTILE_APPROX(discount_pct, 0.5) > 0 ORDER BY activity_month DESC NULLS LAST;
